import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useSearchParams } from 'react-router-dom';
import {
  DEFAULT_CATALOG_LIST_TABLE_CONFIG,
  ErpListHeaderFilters,
  LinCatalogDataGrid,
  LinCatalogHistoryModal,
  LinCatalogListPagination,
  LinCatalogRowActionMenu,
  LinCatalogUiSchemaEditorModal,
  LinListFilterField,
  LinPageLayout,
  Button,
  Input,
  SearchInput,
  SearchTextInput,
  buildCatalogRowMenuItems,
  catalogListTableConfigFromSchema,
  dispatchAppToast,
  useCatalogHistoryModal,
  useErpListSelection,
  useServerPagedListLoading,
  type ErpListTableConfig,
  type LinCatalogRowMenuItem,
} from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { useCatalogUiSchema } from '../../hooks/useCatalogUiSchema';
import { maintenanceService } from '../../services/maintenance/maintenanceService';
import { maintenanceListPermissions } from '../../services/maintenance/permissions';
import type { WorkOrderDto } from '../../services/maintenance/responseModel';
import { lookupLabel, useMaintenanceLookups } from '../../services/maintenance/lookups';
import { catalogUiSchemaService } from '../../services/catalogUiSchema/catalogUiSchemaService';
import {
  buildDynamicGridColumns,
  type UiListColumnBootstrap,
} from '../../utils/bootstrapCatalogUiSchema';
import styles from './MaintenanceListPage.module.css';
import { fromCatalogToolbar } from '../buildRmmsGenericToolbar';

const TEST_ID = 'rmms-maintenance-list';
const PAGE_ID = 'maintenance';
const CATALOG_KIND = 'work-orders';
const ROW_MENU_HINT_KEY = `${TEST_ID}-row-menu-hint-dismissed`;

function formatDue(iso: string): string {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleString('vi-VN');
  } catch {
    return iso;
  }
}

const MaintenanceListPage: React.FC = () => {
  const dispatch = useDispatch();
  const catalogHistory = useCatalogHistoryModal();
  const navigate = useInAppNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const perms = maintenanceListPermissions();
  const { schema, reload: reloadSchema } = useCatalogUiSchema(CATALOG_KIND);
  const lookups = useMaintenanceLookups();

  const [searchDraft, setSearchDraft] = useState('');
  const [statusDraft, setStatusDraft] = useState('');
  const [workTypeDraft, setWorkTypeDraft] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [workTypeFilter, setWorkTypeFilter] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<number>(50);
  const [items, setItems] = useState<WorkOrderDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    row: WorkOrderDto;
  } | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<WorkOrderDto | null>(null);
  const [pendingComplete, setPendingComplete] = useState<WorkOrderDto | null>(null);
  const [progressRow, setProgressRow] = useState<WorkOrderDto | null>(null);
  const [progressPct, setProgressPct] = useState('0');
  const [progressNote, setProgressNote] = useState('');
  const [tableConfig, setTableConfig] = useState<ErpListTableConfig>(() => ({
    ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
    ...catalogListTableConfigFromSchema(undefined),
    resizable: true,
  }));

  useEffect(() => {
    if (!schema?.list) return;
    setTableConfig({
      ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
      ...catalogListTableConfigFromSchema(schema.list),
      resizable: true,
    });
  }, [schema]);

  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const load = useCallback(() => {
    beginFetch();
    maintenanceService
      .getList({
        search: search.trim() || undefined,
        status: statusFilter || undefined,
        workType: workTypeFilter || undefined,
        page,
        pageSize,
      })
      .then((res) => {
        setItems(res.items);
        setTotalCount(res.totalCount);
      })
      .catch(() => {
        setItems([]);
        setTotalCount(0);
      })
      .finally(() => endFetch());
  }, [search, statusFilter, workTypeFilter, page, pageSize, beginFetch, endFetch]);

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) load();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [load]);

  useEffect(() => {
    const form = searchParams.get('form');
    if (!form) return;
    const id = searchParams.get('id');
    if (form === 'create') {
      navigate('/sc-bt/tao-moi', { replace: true });
      return;
    }
    if (id && (form === 'edit' || form === 'view' || form === 'copy')) {
      if (form === 'copy') {
        navigate(`/sc-bt/tao-moi?id=${encodeURIComponent(id)}`, { replace: true });
        return;
      }
      if (form === 'edit') {
        navigate(`/sc-bt/sua?id=${encodeURIComponent(id)}`, { replace: true });
        return;
      }
      navigate(`/sc-bt/${encodeURIComponent(id)}`, { replace: true });
      return;
    }
    setSearchParams({}, { replace: true });
  }, [searchParams, setSearchParams, navigate]);

  const listSelection = useErpListSelection<WorkOrderDto>({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: (r) => r.id,
  });
  const { activeRow, selectActiveRow, clearSelection } = listSelection;

  const applyFilters = useCallback(
    (nextSearch: string, nextStatus: string, nextWorkType: string) => {
      pulseSearch(() => {
        setSearch(nextSearch.trim());
        setStatusFilter(nextStatus);
        setWorkTypeFilter(nextWorkType);
        setPage(1);
      });
    },
    [pulseSearch],
  );

  useEffect(() => {
    const t = window.setTimeout(() => {
      applyFilters(searchDraft, statusDraft, workTypeDraft);
    }, 300);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only re-filter when draft inputs change
  }, [searchDraft, statusDraft, workTypeDraft]);

  const openRow = useCallback(
    (row: WorkOrderDto, mode: 'create' | 'edit' | 'view' | 'copy') => {
      selectActiveRow(row);
      if (mode === 'create') {
        navigate('/sc-bt/tao-moi');
        return;
      }
      if (mode === 'copy') {
        navigate(`/sc-bt/tao-moi?id=${encodeURIComponent(row.id)}`);
        return;
      }
      if (mode === 'edit') {
        navigate(`/sc-bt/sua?id=${encodeURIComponent(row.id)}`);
        return;
      }
      navigate(`/sc-bt/${encodeURIComponent(row.id)}`);
    },
    [selectActiveRow, navigate],
  );

  const openCreate = useCallback(() => {
    if (!perms.canCreate) return;
    navigate('/sc-bt/tao-moi');
  }, [perms.canCreate, navigate]);

  const reloadAll = useCallback(() => {
    setLoadingMode('filter');
    load();
  }, [load, setLoadingMode]);

  const handlePageChange = useCallback((next: number) => {
    setPage(next);
  }, []);

  const handlePageSizeChange = useCallback((next: number) => {
    setPageSize(next);
    setPage(1);
  }, []);

  const handleHistoryToolbar = useCallback(() => {
    if (!activeRow) {
      dispatchAppToast(dispatch, {
        message: 'Chọn một dòng (menu dòng) rồi mở Lịch sử.',
        type: 'info',
      });
      return;
    }
    catalogHistory.openHistory({
      documentType: PAGE_ID,
      documentId: activeRow.id,
      documentCode: activeRow.code,
    });
  }, [activeRow, catalogHistory.openHistory, dispatch]);

  const openConfig = useCallback(() => {
    setConfigOpen(true);
  }, []);

  const deleteRow = useCallback(
    async (row: WorkOrderDto) => {
      if (!perms.canDelete) {
        dispatchAppToast(dispatch, {
          message: 'Không có quyền xóa công việc.',
          type: 'error',
        });
        return;
      }
      setPendingDelete(row);
    },
    [perms.canDelete, dispatch],
  );

  const confirmDelete = useCallback(async () => {
    const row = pendingDelete;
    if (!row) return;
    setPendingDelete(null);
    try {
      await maintenanceService.delete(row.id);
      clearSelection();
      setLoadingMode('filter');
      load();
      dispatchAppToast(dispatch, { message: `Đã xóa ${row.code}.`, type: 'success' });
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Xóa công việc thất bại.',
        type: 'error',
      });
    }
  }, [pendingDelete, clearSelection, setLoadingMode, load, dispatch]);

  const updateProgress = useCallback((row: WorkOrderDto) => {
    setProgressRow(row);
    setProgressPct(String(row.progressPercent ?? 0));
    setProgressNote(row.note ?? '');
  }, []);

  const confirmProgress = useCallback(async () => {
    const row = progressRow;
    if (!row) return;
    const pct = Number(progressPct);
    if (Number.isNaN(pct) || pct < 0 || pct > 100) {
      dispatchAppToast(dispatch, {
        message: 'Tiến độ phải là số từ 0 đến 100.',
        type: 'error',
      });
      return;
    }
    setProgressRow(null);
    try {
      await maintenanceService.progress(row.id, {
        progressPercent: pct,
        note: progressNote.trim() || undefined,
      });
      setLoadingMode('filter');
      load();
      dispatchAppToast(dispatch, { message: `Đã cập nhật tiến độ ${row.code}.`, type: 'success' });
    } catch {
      dispatchAppToast(dispatch, { message: 'Không cập nhật được tiến độ.', type: 'error' });
    }
  }, [progressRow, progressPct, progressNote, load, setLoadingMode, dispatch]);

  const completeRow = useCallback(
    (row: WorkOrderDto) => {
      if (row.status === 'done') {
        dispatchAppToast(dispatch, {
          message: `${row.code} đã nghiệm thu.`,
          type: 'info',
        });
        return;
      }
      setPendingComplete(row);
    },
    [dispatch],
  );

  const confirmComplete = useCallback(async () => {
    const row = pendingComplete;
    if (!row) return;
    setPendingComplete(null);
    try {
      await maintenanceService.complete(row.id);
      setLoadingMode('filter');
      load();
      dispatchAppToast(dispatch, { message: `Đã nghiệm thu ${row.code}.`, type: 'success' });
    } catch {
      dispatchAppToast(dispatch, {
        message: `Nghiệm thu ${row.code} thất bại.`,
        type: 'error',
      });
    }
  }, [pendingComplete, load, setLoadingMode, dispatch]);

  const catalogToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: reloadAll,
      canAdd: perms.canCreate,
      onAdd: openCreate,
      canHistory: true,
      onHistory: handleHistoryToolbar,
      showSchemaConfig: true,
      onEditConfig: openConfig,
      showEdit: Boolean(activeRow && perms.canUpdate),
      showView: Boolean(activeRow && perms.canRead),
      onEdit: activeRow ? () => openRow(activeRow, 'edit') : undefined,
      onView: activeRow ? () => openRow(activeRow, 'view') : undefined,
      canDelete: Boolean(activeRow && perms.canDelete),
      onDelete: activeRow
        ? () => {
            void deleteRow(activeRow);
          }
        : undefined,
    }),
    [
      reloadAll,
      perms.canCreate,
      perms.canUpdate,
      perms.canRead,
      perms.canDelete,
      openCreate,
      handleHistoryToolbar,
      openConfig,
      activeRow,
      openRow,
      deleteRow,
    ],
  );

  const listFilters = useMemo(
    () => (
      <ErpListHeaderFilters
        testIdPrefix={TEST_ID}
        filterCols={3}
      >
        <LinListFilterField testId={`${TEST_ID}-field-search`}>
          <SearchTextInput
            label="Tìm kiếm"
            placeholder="Mã / tuyến / loại / đội / cán bộ…"
            value={searchDraft}
            onChange={setSearchDraft}
            onSearch={() => applyFilters(searchDraft, statusDraft, workTypeDraft)}
            testId={`${TEST_ID}-search-text`}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-status`}>
          <SearchInput
            label="Trạng thái"
            config={lookups.statusConfig}
            value={statusDraft}
            primaryDisplay={lookupLabel(lookups.statusItems, statusDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả trạng thái"
            onChange={(item) => setStatusDraft(item.value)}
            onClear={() => setStatusDraft('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-workType`}>
          <SearchInput
            label="Loại"
            config={lookups.workTypeConfig}
            value={workTypeDraft}
            primaryDisplay={lookupLabel(lookups.workTypeItems, workTypeDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả loại"
            onChange={(item) => setWorkTypeDraft(item.value)}
            onClear={() => setWorkTypeDraft('')}
          />
        </LinListFilterField>
      </ErpListHeaderFilters>
    ),
    [searchDraft, statusDraft, workTypeDraft, applyFilters, lookups],
  );

  const uiColumns = useMemo<UiListColumnBootstrap<WorkOrderDto>[]>(
    () => [
      {
        key: 'code',
        label: 'Mã',
        width: '140px',
        allowSort: true,
        render: (row) => (
          <button
            type="button"
            className={styles.codeLink}
            onClick={() => openRow(row, 'view')}
            data-testid={`${TEST_ID}-code-${row.code}`}
          >
            {row.code}
          </button>
        ),
        getDisplayValue: (r) => r.code,
      },
      {
        key: 'routeName',
        label: 'Tuyến',
        width: '180px',
        allowSort: true,
        render: (row) => row.routeName,
        getDisplayValue: (r) => r.routeName,
      },
      {
        key: 'workType',
        label: 'Loại',
        width: '110px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookups.workTypeLabel(row.workType),
        getDisplayValue: (r) => lookups.workTypeLabel(r.workType),
      },
      {
        key: 'teamName',
        label: 'Đội',
        width: '120px',
        allowSort: true,
        render: (row) => row.teamName || '—',
        getDisplayValue: (r) => r.teamName ?? '',
      },
      {
        key: 'assigneeName',
        label: 'Cán bộ',
        width: '120px',
        allowSort: true,
        render: (row) => row.assigneeName || '—',
        getDisplayValue: (r) => r.assigneeName ?? '',
      },
      {
        key: 'dueAt',
        label: 'Hạn',
        width: '150px',
        control: 'DATE',
        allowSort: true,
        render: (row) => formatDue(row.dueAt),
        getDisplayValue: (r) => r.dueAt,
      },
      {
        key: 'status',
        label: 'Trạng thái',
        width: '100px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookups.statusLabel(row.status),
        getDisplayValue: (r) => lookups.statusLabel(r.status),
      },
      {
        key: 'progressPercent',
        label: 'Tiến độ',
        width: '90px',
        control: 'NUMBER',
        allowSort: true,
        render: (row) => (
          <span className={styles.progressCell}>{row.progressPercent ?? 0}%</span>
        ),
        getDisplayValue: (r) => String(r.progressPercent ?? 0),
      },
    ],
    [openRow, lookups],
  );

  const gridColumns = useMemo(
    () => buildDynamicGridColumns(schema, uiColumns),
    [schema, uiColumns],
  );

  const rowMenuItems = useMemo<LinCatalogRowMenuItem[]>(() => {
    const base = buildCatalogRowMenuItems({
      showView: perms.canRead,
      showEdit: perms.canUpdate,
      showCopy: perms.canCreate,
      showDelete: perms.canDelete,
      showHistory: perms.canRead,
    });
    const extras: LinCatalogRowMenuItem[] = [];
    if (perms.canUpdate) {
      extras.push(
        {
          id: 'progress',
          label: 'Cập nhật tiến độ',
          icon: 'fas fa-tasks',
          separatorBefore: true,
        },
        {
          id: 'complete',
          label: 'Nghiệm thu',
          icon: 'fas fa-clipboard-check',
        },
      );
    }
    return [...base, ...extras];
  }, [perms.canRead, perms.canUpdate, perms.canCreate, perms.canDelete]);

  const handleRowMenuSelect = useCallback(
    (action: string) => {
      const row = rowMenu?.row;
      setRowMenu(null);
      if (!row) return;
      switch (action) {
        case 'view':
          openRow(row, 'view');
          break;
        case 'edit':
          openRow(row, 'edit');
          break;
        case 'copy':
          openRow(row, 'copy');
          break;
        case 'delete':
          void deleteRow(row);
          break;
        case 'history':
          catalogHistory.openHistory({
            documentType: PAGE_ID,
            documentId: row.id,
            documentCode: row.code,
          });
          break;
        case 'progress':
          void updateProgress(row);
          break;
        case 'complete':
          void completeRow(row);
          break;
        default:
          break;
      }
    },
    [rowMenu?.row, openRow, deleteRow, updateProgress, completeRow, catalogHistory.openHistory],
  );

  const emptyMessage =
    search.trim() || statusFilter || workTypeFilter
      ? 'Không có công việc phù hợp bộ lọc.'
      : 'Không có dữ liệu công việc.';

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        filterBarLayout="standard"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Lập lịch sửa chữa / bảo trì',
          titleIconClass: 'fas fa-tools',
          pageId: PAGE_ID,
        }}
        toolbar={fromCatalogToolbar(catalogToolbar)}
        listTitle="Danh sách công việc"
        listRowMenuHelp
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          <LinCatalogListPagination
            testIdPrefix={TEST_ID}
            page={page}
            pageSize={pageSize}
            totalCount={totalCount}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        }
        modals={
          <>
            <LinCatalogRowActionMenu
              open={rowMenu != null}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              testIdPrefix={TEST_ID}
              onClose={() => setRowMenu(null)}
              onSelect={(action) => {
                handleRowMenuSelect(action);
              }}
              items={rowMenuItems}
            />
            <LinCatalogUiSchemaEditorModal
              isOpen={configOpen}
              onClose={() => setConfigOpen(false)}
              testIdPrefix={TEST_ID}
              catalogKind={CATALOG_KIND}
              loadSchema={catalogUiSchemaService.get}
              saveSchema={catalogUiSchemaService.save}
              onSaved={(next) => {
                setTableConfig({
                  ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
                  ...catalogListTableConfigFromSchema(next.list),
                  resizable: true,
                });
                reloadSchema();
                setConfigOpen(false);
              }}
              onError={(message) =>
                dispatchAppToast(dispatch, { message, type: 'error' })
              }
              onSuccess={(message) =>
                dispatchAppToast(dispatch, { message, type: 'success' })
              }
            />
            {catalogHistory.modalProps ? (
              <LinCatalogHistoryModal
                {...catalogHistory.modalProps}
                testIdPrefix={TEST_ID}
                onError={(message) =>
                  dispatchAppToast(dispatch, { message, type: 'error' })
                }
              />
            ) : null}
            {pendingDelete || pendingComplete || progressRow ? (
              <div className={styles.confirmOverlay} data-testid={`${TEST_ID}-confirm`}>
                <div className={styles.confirmCard} role="dialog" aria-modal="true">
                  {pendingDelete ? (
                    <>
                      <p>
                        Xóa công việc «{pendingDelete.code} —{' '}
                        {pendingDelete.title || pendingDelete.routeName}»?
                      </p>
                      <div className={styles.confirmActions}>
                        <Button variant="secondary" size="sm" onClick={() => setPendingDelete(null)}>
                          Hủy
                        </Button>
                        <Button variant="primary" size="sm" onClick={() => void confirmDelete()}>
                          Xóa
                        </Button>
                      </div>
                    </>
                  ) : null}
                  {pendingComplete ? (
                    <>
                      <p>Nghiệm thu công việc {pendingComplete.code}?</p>
                      <div className={styles.confirmActions}>
                        <Button
                          variant="secondary"
                          size="sm"
                          onClick={() => setPendingComplete(null)}
                        >
                          Hủy
                        </Button>
                        <Button variant="primary" size="sm" onClick={() => void confirmComplete()}>
                          Nghiệm thu
                        </Button>
                      </div>
                    </>
                  ) : null}
                  {progressRow ? (
                    <>
                      <p>Cập nhật tiến độ {progressRow.code}</p>
                      <Input
                        label="Tiến độ (0–100)"
                        type="number"
                        value={progressPct}
                        onChange={(e) => setProgressPct(e.target.value)}
                        fullWidth
                      />
                      <Input
                        label="Ghi chú (tuỳ chọn)"
                        value={progressNote}
                        onChange={(e) => setProgressNote(e.target.value)}
                        fullWidth
                      />
                      <div className={styles.confirmActions}>
                        <Button variant="secondary" size="sm" onClick={() => setProgressRow(null)}>
                          Hủy
                        </Button>
                        <Button variant="primary" size="sm" onClick={() => void confirmProgress()}>
                          Lưu
                        </Button>
                      </div>
                    </>
                  ) : null}
                </div>
              </div>
            ) : null}
          </>
        }
      >
        <div className={styles.gridWrap} data-testid={`${TEST_ID}-grid-wrap`}>
          <LinCatalogDataGrid
            testIdPrefix={TEST_ID}
            rows={items}
            page={page}
            pageSize={pageSize}
            columns={gridColumns}
            getRowId={(r) => r.id}
            selection={listSelection}
            tableConfig={tableConfig}
            paginateClient={false}
            empty={
              <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
                {emptyMessage}
              </div>
            }
            onRowOpenActionMenu={({ row, x, y }) => {
              selectActiveRow(row);
              setRowMenu({ row, x, y });
            }}
            onRowDoubleClick={(row) => openRow(row, 'view')}
            rowMenuHintDismissStorageKey={ROW_MENU_HINT_KEY}
          />
        </div>
      </LinPageLayout>
    </div>
  );
};

export default MaintenanceListPage;
