import type { ReactNode } from 'react';
import type {
  CatalogUiField,
  CatalogUiSchema,
  SaveCatalogUiSchema,
  LinCatalogDataColumn,
  LinCatalogDataColumnRenderCtx,
} from '@linm-soft-org/linm-web-common-components';
import { listVisibleFields } from './catalogUiSchemaGrid';

/** UI column used to bootstrap BE schema + bind renderers for dynamic grid. */
export type UiListColumnBootstrap<T> = {
  key: string;
  label: string;
  width?: string | null;
  control?: string;
  treeIndent?: boolean;
  showFilter?: boolean;
  allowSort?: boolean;
  getDisplayValue?: (row: T) => string;
  render: (row: T, ctx: LinCatalogDataColumnRenderCtx) => ReactNode;
};

export type RmmsCatalogUiSchema = CatalogUiSchema & { hasSavedOverride?: boolean };

export function buildSaveBodyFromUiColumns<T>(
  columns: UiListColumnBootstrap<T>[],
  opts?: { schemaVersion?: number; hintText?: string },
): SaveCatalogUiSchema & { bootstrapFromUi: true } {
  const fields: CatalogUiField[] = columns.map((c, i) => ({
    key: c.key,
    control: c.control ?? 'TEXT',
    label: c.label,
    configurable: true,
    systemOnly: false,
    list: {
      visible: true,
      order: i + 1,
      width: c.width ?? null,
      showFilter: c.showFilter ?? false,
      allowSort: c.allowSort ?? false,
    },
    lookup: {
      visible: c.key === 'code' || c.key === 'name',
      order: i + 1,
      width: c.width ?? null,
    },
    proposal: { editable: false, order: i + 1 },
  }));

  const searchKeys = columns
    .map((c) => c.key)
    .filter((k) => k === 'code' || k === 'name');
  return {
    schemaVersion: opts?.schemaVersion ?? 1,
    bootstrapFromUi: true,
    hintText: opts?.hintText ?? null,
    fields,
    lookup: {
      searchFieldKeys: searchKeys.length
        ? searchKeys
        : columns.slice(0, 2).map((c) => c.key),
      primaryDisplayKey:
        columns.find((c) => c.key === 'name')?.key ?? columns[0]?.key ?? 'name',
      secondaryDisplayKey:
        columns.find((c) => c.key === 'code')?.key ?? null,
    },
    list: {
      searchFieldKeys: searchKeys.length
        ? searchKeys
        : columns.map((c) => c.key),
      defaultPageSize: 50,
      stickyHeader: true,
      heightMode: 'auto',
      height: null,
      resizableColumns: true,
    },
  };
}

/**
 * Dynamic grid columns from BE schema order/visibility/width.
 * Fallback = UI columns when schema not ready.
 */
export function buildDynamicGridColumns<T>(
  schema: RmmsCatalogUiSchema | null | undefined,
  uiColumns: UiListColumnBootstrap<T>[],
): LinCatalogDataColumn<T>[] {
  const byKey = new Map(uiColumns.map((c) => [c.key, c]));
  const visible = listVisibleFields(schema);

  if (!visible.length) {
    return uiColumns.map((c) => ({
      key: c.key,
      label: c.label,
      width: c.width,
      treeIndent: c.treeIndent,
      showFilter: c.showFilter ?? false,
      allowSort: c.allowSort ?? false,
      getDisplayValue: c.getDisplayValue,
      render: c.render,
    }));
  }

  return visible.map((field) => {
    const ui = byKey.get(field.key);
    if (!ui) {
      return {
        key: field.key,
        label: field.label,
        width: field.list?.width ?? undefined,
        showFilter: field.list?.showFilter,
        allowSort: field.list?.allowSort,
        getDisplayValue: (row: T) => {
          const rec = row as Record<string, unknown>;
          const v = rec[field.key];
          return v == null ? '' : String(v);
        },
        render: (row: T) => {
          const rec = row as Record<string, unknown>;
          const v = rec[field.key];
          return v == null || v === '' ? '—' : String(v);
        },
      } satisfies LinCatalogDataColumn<T>;
    }
    return {
      key: field.key,
      label: field.label || ui.label,
      width: field.list?.width ?? ui.width,
      treeIndent: ui.treeIndent,
      showFilter: field.list?.showFilter ?? ui.showFilter ?? false,
      allowSort: field.list?.allowSort ?? ui.allowSort ?? false,
      getDisplayValue: ui.getDisplayValue,
      render: ui.render,
    } satisfies LinCatalogDataColumn<T>;
  });
}

/** No tenant override yet → first Save = create/register (not edit). */
export function needsUiSchemaBootstrap(
  schema: RmmsCatalogUiSchema | null | undefined,
): boolean {
  if (!schema) return true;
  if (schema.hasSavedOverride === true) return false;
  return true;
}
